  final match = _liveBoard.firstMatch(harness.screenText);
  final count = match == null ? null : int.parse(match.group(1)!);
  if (count != null && count >= 1 && count <= 9) {
    mid = count;
    break;
  }
  await Future<void>.delayed(const Duration(milliseconds: 50));
}
