        'tool_call': {
          'id': 'c1-$i',
          'name': 'bash',
          'arguments': {
            'command': 'sleep ${2 + i} && echo p573-job-$i',
            'background': true,
          },
        },
      },
  ],
  [
    {'text': 'p573 wave launched'},
  ],
];

/// The live collapsed board row: ten started, nothing settled yet.
